#!/usr/bin/env python3
"""Primitive `.flow` mutations: node/edge CRUD, variables, output mappings.

Each subcommand touches every array the operation implies (nodes, edges, definitions,
variables.nodes, variables.variableUpdates, layout.nodes) in one pass and writes the file
back with 2-space indent.
"""
import argparse
import json
import re
import sys

import flow_lib as fl

ID_RE = re.compile(r"^[A-Za-z]")


def _check_id(kind, value):
    if not ID_RE.match(value or ""):
        fl.die("%s id %r must start with a letter (XML NCName); never a bare UUID or leading digit" % (kind, value))


def _load_definition(path):
    with open(path) as fh:
        payload = json.load(fh)
    return fl.unwrap_definition(payload)


def _skeleton_outputs(ntype, outputs):
    if fl.is_terminal(ntype) or not outputs:
        return {}
    if fl.is_trigger(ntype):
        return {
            "output": {
                "type": "object",
                "description": "Data passed when triggering the process.",
                "source": "null",
                "var": "output",
            }
        }
    if fl.is_orch_job(ntype):
        return {
            "error": {
                "type": "object",
                "description": "Error information if the node fails.",
                "source": "=Error",
                "var": "error",
            }
        }
    block = {}
    for out in outputs:
        if out == "error":
            block["error"] = {
                "type": "object",
                "description": "Error information if the node fails.",
                "source": "=Error",
                "var": "error",
            }
        else:
            block[out] = {
                "type": "object",
                "description": "The return value of the node.",
                "source": "=result.response",
                "var": out,
            }
    return block


def _sync_node_variables(flow, nid, outputs):
    existing = {v.get("id") for v in flow["variables"]["nodes"] if isinstance(v, dict)}
    for out in outputs:
        vid = "%s.%s" % (nid, out)
        if vid in existing:
            continue
        flow["variables"]["nodes"].append(
            {"id": vid, "type": "object", "binding": {"nodeId": nid, "outputId": out}}
        )


def add_node(args):
    flow = fl.load(args.flow)
    nodes = fl.node_map(flow)
    _check_id("node", args.id)
    if args.id in nodes:
        fl.die("node id %r already exists" % args.id)
    if fl.is_cli_owned(args.type) and not args.allow_cli_owned:
        fl.die(
            "%s is CLI-owned: add it with `uip maestro flow node add` + `node configure`, "
            "not by direct authoring (pass --allow-cli-owned only to override)" % args.type,
            3,
        )
    definition = _load_definition(args.definition_file) if args.definition_file else None
    version = args.type_version
    if definition is not None:
        dver = definition.get("version")
        if version is None:
            version = dver
        elif dver is not None and str(dver) != str(version):
            fl.die("--type-version %r does not string-match the definition version %r" % (version, dver))
    if version is None:
        fl.die("--type-version is required when no --definition-file is given")

    node = {
        "id": args.id,
        "type": args.type,
        "typeVersion": str(version),
        "display": {"label": args.label or args.id},
        "inputs": json.loads(args.inputs) if args.inputs else {},
    }
    if args.outputs == "auto":
        outputs = fl.declared_outputs(definition) if definition else []
        if not outputs and not fl.is_terminal(args.type):
            outputs = ["output"] if fl.is_trigger(args.type) else ["output", "error"]
    elif args.outputs == "none":
        outputs = []
    else:
        outputs = [o.strip() for o in args.outputs.split(",") if o.strip()]
    block = _skeleton_outputs(args.type, outputs)
    if block:
        node["outputs"] = block
    flow["nodes"].append(node)

    added_def = False
    if definition is not None and fl.definition_for(flow, node) is None:
        flow["definitions"].append(definition)
        added_def = True
    if not fl.is_terminal(args.type):
        _sync_node_variables(flow, args.id, outputs)
    if args.type != "stickyNote":
        flow["layout"]["nodes"].setdefault(
            args.id,
            {"position": {"x": 0, "y": 0}, "size": fl.expected_size(args.type), "collapsed": False},
        )
    fl.save(args.flow, flow)
    print("added node %s (%s v%s); definition %s; variables.nodes +%d" % (
        args.id, args.type, version, "added" if added_def else "reused/absent", len(outputs)))
    return 0


def delete_node(args):
    flow = fl.load(args.flow)
    nodes = fl.node_map(flow)
    if args.id not in nodes:
        fl.die("no node with id %r" % args.id)
    node = nodes[args.id]
    flow["nodes"] = [n for n in flow["nodes"] if n.get("id") != args.id]
    dropped_edges = [e for e in flow["edges"] if args.id in (e.get("sourceNodeId"), e.get("targetNodeId"))]
    flow["edges"] = [e for e in flow["edges"] if e not in dropped_edges]
    flow["variables"]["nodes"] = [
        v for v in flow["variables"]["nodes"]
        if not (isinstance(v, dict) and (v.get("binding") or {}).get("nodeId") == args.id)
    ]
    updates = flow["variables"].get("variableUpdates")
    dropped_updates = 0
    if isinstance(updates, dict) and args.id in updates:
        del updates[args.id]
        dropped_updates = 1
    flow["layout"]["nodes"].pop(args.id, None)
    still_used = any(n.get("type") == node.get("type") for n in flow["nodes"])
    pruned_def = False
    if not still_used:
        before = len(flow["definitions"])
        flow["definitions"] = [
            d for d in flow["definitions"]
            if (d.get("nodeType") or d.get("type")) != node.get("type")
        ]
        pruned_def = len(flow["definitions"]) < before
    fl.save(args.flow, flow)
    print("deleted node %s; edges -%d; variableUpdates -%d; definition %s" % (
        args.id, len(dropped_edges), dropped_updates, "pruned" if pruned_def else "kept (still used)"))
    if node.get("type", "").startswith("uipath.connector."):
        print("note: connector binding in bindings_v2.json is shared per connector — remove it only if no remaining node uses that connector")
    return 0


def add_edge(args):
    flow = fl.load(args.flow)
    nodes = fl.node_map(flow)
    for role, nid in (("source", args.source), ("target", args.target)):
        if nid not in nodes:
            fl.die("%s node %r does not exist in the flow" % (role, nid))
    if not args.target_port:
        fl.die("--target-port is required on every edge; validate rejects edges without it")
    eid = args.id or "edge_%s_%s_%s_%s" % (args.source, args.source_port, args.target, args.target_port)
    _check_id("edge", eid)
    if any(e.get("id") == eid for e in flow["edges"]):
        fl.die("edge id %r already exists" % eid)
    flow["edges"].append({
        "id": eid,
        "sourceNodeId": args.source,
        "sourcePort": args.source_port,
        "targetNodeId": args.target,
        "targetPort": args.target_port,
    })
    flagged = False
    if args.source_port == "error":
        nodes[args.source].setdefault("inputs", {})["errorHandlingEnabled"] = True
        flagged = True
    fl.save(args.flow, flow)
    print("added edge %s%s" % (eid, "; set inputs.errorHandlingEnabled on " + args.source if flagged else ""))
    return 0


def delete_edge(args):
    flow = fl.load(args.flow)
    if args.id:
        keep = [e for e in flow["edges"] if e.get("id") != args.id]
    elif args.source and args.target:
        keep = [
            e for e in flow["edges"]
            if not (e.get("sourceNodeId") == args.source and e.get("targetNodeId") == args.target
                    and (args.source_port is None or e.get("sourcePort") == args.source_port))
        ]
    else:
        fl.die("pass --id, or both --source and --target")
    removed = len(flow["edges"]) - len(keep)
    if removed == 0:
        fl.die("no matching edge found")
    flow["edges"] = keep
    fl.save(args.flow, flow)
    print("deleted %d edge(s)" % removed)
    return 0


def set_input(args):
    flow = fl.load(args.flow)
    nodes = fl.node_map(flow)
    if args.node not in nodes:
        fl.die("no node with id %r" % args.node)
    node = nodes[args.node]
    if fl.is_cli_owned(node.get("type", "")) and args.key.split(".")[0] == "detail" and not args.allow_cli_owned:
        fl.die("inputs.detail on %s is CLI-owned: use `uip maestro flow node configure --detail`" % node.get("type"), 3)
    value = json.loads(args.value) if args.json else args.value
    target = node.setdefault("inputs", {})
    parts = args.key.split(".")
    for p in parts[:-1]:
        nxt = target.get(p)
        if not isinstance(nxt, dict):
            nxt = {}
            target[p] = nxt
        target = nxt
    target[parts[-1]] = value
    fl.save(args.flow, flow)
    print("set inputs.%s on %s" % (args.key, args.node))
    return 0


def add_variable(args):
    flow = fl.load(args.flow)
    globs = flow["variables"]["globals"]
    if any(isinstance(v, dict) and v.get("id") == args.id for v in globs):
        fl.die("variable %r already declared" % args.id)
    var = {"id": args.id, "direction": args.direction, "type": args.type}
    if args.sub_type:
        var["subType"] = args.sub_type
    if args.default is not None:
        var["defaultValue"] = json.loads(args.default)
    if args.description:
        var["description"] = args.description
    if args.trigger_node_id:
        var["triggerNodeId"] = args.trigger_node_id
    globs.append(var)
    fl.save(args.flow, flow)
    hint = ""
    if args.direction == "out":
        hint = "; map it on every reachable End node (add-output-mapping)"
    print("declared %s variable %s%s" % (args.direction, args.id, hint))
    return 0


def add_output_mapping(args):
    flow = fl.load(args.flow)
    nodes = fl.node_map(flow)
    if args.end_node not in nodes:
        fl.die("no node with id %r" % args.end_node)
    node = nodes[args.end_node]
    if not fl.is_terminal(node.get("type", "")):
        fl.die("%s is %s, not an End/terminate node" % (args.end_node, node.get("type")))
    node.setdefault("outputs", {})[args.var] = {"source": args.source}
    fl.save(args.flow, flow)
    print("mapped %s on %s" % (args.var, args.end_node))
    return 0


def add_variable_update(args):
    flow = fl.load(args.flow)
    nodes = fl.node_map(flow)
    if args.node not in nodes:
        fl.die("no node with id %r" % args.node)
    declared = {v.get("id"): v for v in flow["variables"]["globals"] if isinstance(v, dict)}
    var = declared.get(args.variable)
    if var is None:
        fl.die("variable %r is not declared in variables.globals" % args.variable)
    if var.get("direction") != "inout":
        fl.die("only inout variables can be updated via variableUpdates; %r is %r" % (args.variable, var.get("direction")))
    updates = flow["variables"].setdefault("variableUpdates", {})
    updates.setdefault(args.node, []).append({"variableId": args.variable, "expression": args.expression})
    fl.save(args.flow, flow)
    print("added variableUpdate %s on %s" % (args.variable, args.node))
    return 0


def build_parser():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = p.add_subparsers(dest="cmd", required=True)

    a = sub.add_parser("add-node", help="insert a node + definition + variables.nodes + layout entry")
    a.add_argument("--flow", required=True)
    a.add_argument("--id", required=True, help="camelCase, must start with a letter")
    a.add_argument("--type", required=True)
    a.add_argument("--type-version", help="omit when --definition-file supplies it")
    a.add_argument("--label")
    a.add_argument("--definition-file", help="`uip maestro flow registry get <type> --output json` saved to a file")
    a.add_argument("--inputs", help="JSON object for inputs")
    a.add_argument("--outputs", default="auto", help="auto | none | comma-separated output ids")
    a.add_argument("--allow-cli-owned", action="store_true", help="override the CLI-owned refusal")
    a.set_defaults(fn=add_node)

    d = sub.add_parser("delete-node", help="remove a node and cascade edges/variables/updates/layout/definition")
    d.add_argument("--flow", required=True)
    d.add_argument("--id", required=True)
    d.set_defaults(fn=delete_node)

    e = sub.add_parser("add-edge", help="add an edge with both ports; sets errorHandlingEnabled for error edges")
    e.add_argument("--flow", required=True)
    e.add_argument("--source", required=True)
    e.add_argument("--source-port", required=True)
    e.add_argument("--target", required=True)
    e.add_argument("--target-port", required=True)
    e.add_argument("--id", help="default edge_<source>_<sourcePort>_<target>_<targetPort>")
    e.set_defaults(fn=add_edge)

    x = sub.add_parser("delete-edge", help="remove an edge by id or by endpoints")
    x.add_argument("--flow", required=True)
    x.add_argument("--id")
    x.add_argument("--source")
    x.add_argument("--source-port")
    x.add_argument("--target")
    x.set_defaults(fn=delete_edge)

    s = sub.add_parser("set-input", help="in-place inputs update (dotted key path), preserves node id")
    s.add_argument("--flow", required=True)
    s.add_argument("--node", required=True)
    s.add_argument("--key", required=True, help="e.g. expression or detail.queryParameters.recordId")
    s.add_argument("--value", required=True)
    s.add_argument("--json", action="store_true", help="parse --value as JSON")
    s.add_argument("--allow-cli-owned", action="store_true")
    s.set_defaults(fn=set_input)

    v = sub.add_parser("add-variable", help="declare a workflow variable in variables.globals")
    v.add_argument("--flow", required=True)
    v.add_argument("--id", required=True)
    v.add_argument("--direction", required=True, choices=["in", "out", "inout"])
    v.add_argument("--type", default="string", choices=["string", "number", "boolean", "object", "array", "file"])
    v.add_argument("--sub-type")
    v.add_argument("--default", help="JSON literal")
    v.add_argument("--description")
    v.add_argument("--trigger-node-id")
    v.set_defaults(fn=add_variable)

    o = sub.add_parser("add-output-mapping", help="map an out variable on an End/terminate node")
    o.add_argument("--flow", required=True)
    o.add_argument("--end-node", required=True)
    o.add_argument("--var", required=True)
    o.add_argument("--source", required=True, help="e.g. =js:$vars.calc.output.amount")
    o.set_defaults(fn=add_output_mapping)

    u = sub.add_parser("add-variable-update", help="add a variableUpdates entry for an inout variable")
    u.add_argument("--flow", required=True)
    u.add_argument("--node", required=True)
    u.add_argument("--variable", required=True)
    u.add_argument("--expression", required=True)
    u.set_defaults(fn=add_variable_update)
    return p


def main(argv=None):
    args = build_parser().parse_args(argv)
    return args.fn(args)


if __name__ == "__main__":
    sys.exit(main())

